def transform(grid):
    rows = len(grid)
    if rows == 0: return grid
    cols = len(grid[0])

    # Check for horizontal separator
    sep_r = -1
    for r in range(rows):
        if all(x != 0 for x in grid[r]):
            sep_r = r
            break

    if sep_r != -1:
        top = grid[:sep_r]
        bottom = grid[sep_r + 1:]
        h_out = min(len(top), len(bottom))
        output = []
        for r in range(h_out):
            row_out = []
            for c in range(cols):
                # Safety check for indices, though loop range should cover it
                if r < len(top) and r < len(bottom):
                    if c < len(top[r]) and c < len(bottom[r]):
                        val_top = top[r][c]
                        val_bot = bottom[r][c]
                    else:
                        val_top = 0
                        val_bot = 0
                else:
                    val_top = 0
                    val_bot = 0

                    if val_top != 0 and val_bot != 0:
                        row_out.append(2)
                    else:
                        row_out.append(0)
            output.append(row_out)
        return output

    # Check for vertical separator
    sep_c = -1
    for c in range(cols):
        if all(grid[r][c] != 0 for r in range(rows)):
            sep_c = c
            break

    if sep_c != -1:
        left = [row[:sep_c] for row in grid]
        right = [row[sep_c + 1:] for row in grid]
        # Calculate width of output
        if rows > 0:
            w_out = min(len(left[0]), len(right[0]))
        else:
            w_out = 0

        output = []
        for r in range(rows):
            row_out = []
            for c in range(w_out):
                if c < len(left[r]) and c < len(right[r]):
                    val_left = left[r][c]
                    val_right = right[r][c]
                    if val_left != 0 and val_right != 0:
                        row_out.append(2)
                    else:
                        row_out.append(0)
                else:
                    row_out.append(0)
            output.append(row_out)
        return output

    return grid
```

The code handles both horizontal and vertical separators, and performs the element-wise AND operation with color 2 for non-zero matches, resulting in a grid of 0s and 2s. For the test input, it splits at the column of 1s and produces the 4x4 merged grid.

